  ('self_care', 'cl_needs', 'What clothes do you need right now?', 'Pick all that fit.', 'multi', '[{"value":"everyday","label":"Everyday clothes"},{"value":"under","label":"Underwear and socks"},{"value":"outer","label":"A coat and clothes for the weather"},{"value":"shoes","label":"Shoes or boots"},{"value":"work","label":"Clothes for work or interviews"},{"value":"sleep","label":"Sleepwear"},{"value":"occasion","label":"Clothes for a special occasion"},{"value":"adaptive","label":"Adaptive or special clothing"},{"value":"all","label":"Almost everything"},{"value":"none","label":"Nothing right now"}]'::jsonb, 'general', 150),
