  ('identity_legal', 'ji_history', 'Do you have a criminal record, or have you been in jail or prison?', 'This is private. Only you see it, unless you share "ID, papers and legal matters".', 'choice', '[{"value":"no","label":"No"},{"value":"record","label":"I have a record"},{"value":"past","label":"I was in jail or prison in the past"},{"value":"recent","label":"I came home in the last year"},{"value":"prefer_not","label":"I''d rather not say"}]'::jsonb, 'legal', 110),
  ('identity_legal', 'ji_supervision', 'Are you on probation, parole or extended supervision now?', null, 'choice', '[{"value":"no","label":"No"},{"value":"probation","label":"Probation"},{"value":"parole","label":"Parole"},{"value":"extended","label":"Extended supervision"},{"value":"other","label":"Something else"}]'::jsonb, 'legal', 120),
