  ('identity_legal', 'vet_served', 'Have you served in the U.S. military, the National Guard or the Reserves?', null, 'choice', '[{"value":"yes","label":"Yes"},{"value":"no","label":"No"},{"value":"prefer_not","label":"I''d rather not say"}]'::jsonb, 'legal', 180),
  ('identity_legal', 'vet_papers', 'Do you have your discharge papers (DD-214)?', null, 'choice', '[{"value":"yes","label":"Yes"},{"value":"no","label":"No"},{"value":"not_sure","label":"I''m not sure"}]'::jsonb, 'legal', 190),
  ('identity_legal', 'vet_va', 'Which veterans'' services do you use now?', 'Pick all that fit.', 'multi', '[{"value":"health","label":"VA health care"},{"value":"disability","label":"VA disability pay"},{"value":"pension","label":"VA pension"},{"value":"education","label":"GI Bill or education help"},{"value":"housing","label":"VA housing help (HUD-VASH or SSVF)"},{"value":"none","label":"None"},{"value":"not_sure","label":"I''m not sure what I can get"}]'::jsonb, 'legal', 200),
  ('identity_legal', 'vet_help', 'Would you like help connecting with veterans'' services?', 'You can change this any time.', 'choice', '[{"value":"now","label":"Yes, now"},{"value":"later","label":"Maybe later"},{"value":"no","label":"No, thank you"}]'::jsonb, 'legal', 210),
  ('finances', 'dc_kinds', 'What kinds of debt do you have, if any?', 'Pick all that fit. This is private: only you see it, unless you share "Money".', 'multi', '[{"value":"none","label":"None"},{"value":"cards","label":"Credit cards"},{"value":"medical","label":"Medical bills"},{"value":"student","label":"Student loans"},{"value":"utilities","label":"Past-due utility bills"},{"value":"rent","label":"Past-due rent or a landlord judgment"},{"value":"payday","label":"Payday or title loans"},{"value":"car","label":"A car loan"},{"value":"court","label":"Court fines or fees"},{"value":"support","label":"Back child support"},{"value":"taxes","label":"Taxes owed"},{"value":"other","label":"Something else"}]'::jsonb, 'financial', 110),
  ('finances', 'dc_total', 'About how much do you owe in all?', 'A rough number is fine.', 'money', '[]'::jsonb, 'financial', 120),
